  //       s.send_to_noc_load_response_pkt.val @= s.response_crossbar.send[i].val
  //       s.response_crossbar.send[i].rdy @= s.send_to_noc_load_response_pkt.rdy
  //     elif has_dma_ports:
  //       s.send_to_controller_spm_rd_resp.msg      @= DmaSpmReadRespType(
  //         trunc(s.response_crossbar.send[i].msg.data.payload, DmaSpmDataType))
  //       s.send_to_controller_spm_rd_resp.val      @= s.response_crossbar.send[i].val
  //       s.response_crossbar.send[i].rdy @= s.send_to_controller_spm_rd_resp.rdy
  // 
  //   # Handles the request (not response) towards the others via the NoC. The dst would be
  //   # updated in the controller.
  //   s.send_to_noc_load_request_pkt.msg @= \
  //       NocPktType(s.cgra_id, # src
  //                   0, # dst
  //                   s.idTo2d_x_lut[s.cgra_id], # src_x
  //                   s.idTo2d_y_lut[s.cgra_id], # src_y
  //                   0, # dst_x
  //                   0, # dst_y
  //                   0, # src_tile_id
  //                   0, # dst_tile_id
  //                   trunc(s.read_crossbar.send[num_banks_per_cgra].msg.src, NocRemoteSrcPortType), # remote_src_port
  //                   0, # opaque
  //                   0, # vc_id
  //                   CgraPayloadType(
  //                       CMD_LOAD_REQUEST,
  //                       0,
  //                       s.read_crossbar.send[num_banks_per_cgra].msg.addr, 0, 0))
  // 
  //   s.send_to_noc_load_request_pkt.val @= s.read_crossbar.send[num_banks_per_cgra].val 
  //   # TODO: https://github.com/tancheng/VectorCGRA/issues/26 -- Modify this part for non-blocking access.
  //   # 'val` indicates the data is arbitrated successfully.
  //   s.recv_from_noc_load_response_pkt.rdy @= s.response_crossbar.recv[num_banks_per_cgra].rdy
  //   s.response_crossbar.recv[num_banks_per_cgra].val @= s.recv_from_noc_load_response_pkt.val
  //   s.response_crossbar.recv[num_banks_per_cgra].msg @= \
  //       MemResponsePktType(num_banks_per_cgra,
  //                          zext(s.recv_from_noc_load_response_pkt.msg.remote_src_port, XbarInRdType),
  //                          s.recv_from_noc_load_response_pkt.msg.payload.data_addr,
  //                          s.recv_from_noc_load_response_pkt.msg.payload.data,
  //                          s.recv_from_noc_load_response_pkt.msg.src,
  //                          s.recv_from_noc_load_response_pkt.msg.src_tile_id,
  //                          0)
  // 
  //   # Allows other load request towards NoC when the previous one is not responded. There
  //   # could be out-of-order load response, i.e., potential consistency issue.
  //   s.read_crossbar.send[num_banks_per_cgra].rdy @= s.send_to_noc_load_request_pkt.rdy
  // 
  //   # Handles the write port towards the NoC.
  //   s.send_to_noc_store_pkt.msg @= \
  //       NocPktType(s.cgra_id, # src
  //                   0, # dst
  //                   s.idTo2d_x_lut[s.cgra_id], # src_x
  //                   s.idTo2d_y_lut[s.cgra_id], # src_y
  //                   0, # dst_x
  //                   0, # dst_y
  //                   0, # src_tile_id
  //                   0, # dst_tile_id
  //                   trunc(s.write_crossbar.send[num_banks_per_cgra].msg.src, NocRemoteSrcPortType), # remote_src_port
  //                   0, # opaque
  //                   0, # vc_id
  //                   CgraPayloadType(
  //                       CMD_STORE_REQUEST,
  //                       s.write_crossbar.send[num_banks_per_cgra].msg.data,
  //                       s.write_crossbar.send[num_banks_per_cgra].msg.addr, 0, 0))
  // 
  //   s.send_to_noc_store_pkt.val @= s.write_crossbar.send[num_banks_per_cgra].val
  //   s.write_crossbar.send[num_banks_per_cgra].rdy @= s.send_to_noc_store_pkt.rdy
  
  always_comb begin : update_all
    for ( int unsigned i = 1'd0; i < 1'( __const__num_rd_tiles_at_update_all ); i += 1'd1 )
      recv_raddr__rdy[1'(i)] = 1'd0;
    recv_from_noc_load_request__rdy = 1'd0;
    for ( int unsigned i = 1'd0; i < 2'( __const__num_wr_tiles_at_update_all ); i += 1'd1 )
      recv_waddr__rdy[2'(i)] = 1'd0;
    recv_from_noc_store_request__rdy = 1'd0;
    for ( int unsigned i = 1'd0; i < 1'( __const__num_rd_tiles_at_update_all ); i += 1'd1 ) begin
      send_rdata__val[1'(i)] = 1'd0;
      send_rdata__msg[1'(i)] = { 32'd0, 1'd0, 1'd0, 1'd0 };
    end
    send_to_noc_load_response_pkt__val = 1'd0;
    send_to_noc_load_response_pkt__msg = { 2'd0, 2'd0, 1'd0, 1'd0, 1'd0, 1'd0, 3'd0, 3'd0, 1'd0, 8'd0, 2'd0, { 6'd0, 35'd0, 7'd0, 119'd0, 3'd0 } };
    for ( int unsigned i = 1'd0; i < 2'( __const__num_wr_tiles_at_update_all ); i += 1'd1 )
      recv_wdata__rdy[2'(i)] = 1'd0;
    send_to_noc_store_pkt__msg = { 2'd0, 2'd0, 1'd0, 1'd0, 1'd0, 1'd0, 3'd0, 3'd0, 1'd0, 8'd0, 2'd0, { 6'd0, 35'd0, 7'd0, 119'd0, 3'd0 } };
    send_to_noc_store_pkt__val = 1'd0;
    for ( int unsigned i = 1'd0; i < 2'( __const__num_xbar_in_rd_ports_at_update_all ); i += 1'd1 ) begin
      read_crossbar__recv__val[1'(i)] = 1'd0;
      read_crossbar__recv__msg[1'(i)] = { 1'd0, 2'd0, 7'd0, { 32'd0, 1'd0, 1'd0, 1'd0 }, 2'd0, 3'd0, 1'd0 };
    end
    recv_from_noc_load_response_pkt__rdy = 1'd0;
    for ( int unsigned i = 1'd0; i < 3'( __const__num_xbar_in_wr_ports_at_update_all ); i += 1'd1 ) begin
      write_crossbar__recv__val[2'(i)] = 1'd0;
      write_crossbar__recv__msg[2'(i)] = { 2'd0, 2'd0, 7'd0, { 32'd0, 1'd0, 1'd0, 1'd0 }, 2'd0, 3'd0, 1'd0 };
    end
    recv_from_controller_spm_wr_req__rdy = 1'd0;
    recv_from_controller_spm_rd_req__rdy = 1'd0;
    send_to_controller_spm_rd_resp__val = 1'd0;
    send_to_controller_spm_rd_resp__msg = 32'd0;
    send_to_noc_load_request_pkt__msg = { 2'd0, 2'd0, 1'd0, 1'd0, 1'd0, 1'd0, 3'd0, 3'd0, 1'd0, 8'd0, 2'd0, { 6'd0, 35'd0, 7'd0, 119'd0, 3'd0 } };
    send_to_noc_load_request_pkt__val = 1'd0;
    for ( int unsigned i = 1'd0; i < 1'( __const__num_rd_tiles_at_update_all ); i += 1'd1 ) begin
      read_crossbar__recv__val[1'(i)] = recv_raddr__val[1'(i)];
      read_crossbar__recv__msg[1'(i)] = rd_pkt[1'(i)];
      recv_raddr__rdy[1'(i)] = read_crossbar__recv__rdy[1'(i)];
    end
    read_crossbar__recv__val[1'( __const__num_rd_tiles_at_update_all )] = recv_from_noc_load_request__val;
    read_crossbar__recv__msg[1'( __const__num_rd_tiles_at_update_all )] = rd_pkt[1'( __const__num_rd_tiles_at_update_all )];
    recv_from_noc_load_request__rdy = read_crossbar__recv__rdy[1'( __const__num_rd_tiles_at_update_all )];
    if ( 1'( __const__has_dma_ports_at_update_all ) ) begin
      __tmpvar__update_all_dma_rd_idx = 1'd1;
      read_crossbar__recv__val[__tmpvar__update_all_dma_rd_idx] = recv_from_controller_spm_rd_req__val;
      read_crossbar__recv__msg[__tmpvar__update_all_dma_rd_idx] = rd_pkt[__tmpvar__update_all_dma_rd_idx];
      recv_from_controller_spm_rd_req__rdy = read_crossbar__recv__rdy[__tmpvar__update_all_dma_rd_idx];
    end
    for ( int unsigned i = 1'd0; i < 2'( __const__num_wr_tiles_at_update_all ); i += 1'd1 ) begin
      write_crossbar__recv__val[2'(i)] = recv_waddr__val[2'(i)];
      write_crossbar__recv__msg[2'(i)] = wr_pkt[2'(i)];
      recv_waddr__rdy[2'(i)] = write_crossbar__recv__rdy[2'(i)];
      recv_wdata__rdy[2'(i)] = write_crossbar__recv__rdy[2'(i)];
    end
    write_crossbar__recv__val[2'( __const__num_wr_tiles_at_update_all )] = recv_from_noc_store_request__val;
    write_crossbar__recv__msg[2'( __const__num_wr_tiles_at_update_all )] = wr_pkt[2'( __const__num_wr_tiles_at_update_all )];
    recv_from_noc_store_request__rdy = write_crossbar__recv__rdy[2'( __const__num_wr_tiles_at_update_all )];
    if ( 1'( __const__has_dma_ports_at_update_all ) ) begin
      __tmpvar__update_all_dma_wr_idx = 2'd3;
      write_crossbar__recv__val[__tmpvar__update_all_dma_wr_idx] = recv_from_controller_spm_wr_req__val;
      write_crossbar__recv__msg[__tmpvar__update_all_dma_wr_idx] = wr_pkt[__tmpvar__update_all_dma_wr_idx];
      recv_from_controller_spm_wr_req__rdy = write_crossbar__recv__rdy[__tmpvar__update_all_dma_wr_idx];
    end
    for ( int unsigned i = 1'd0; i < 2'( __const__num_xbar_in_rd_ports_at_update_all ); i += 1'd1 )
      if ( 1'(i) < 1'( __const__num_rd_tiles_at_update_all ) ) begin
        send_rdata__msg[1'( 1'(i) )] = response_crossbar__send__msg[1'(i)].data;
        send_rdata__val[1'( 1'(i) )] = response_crossbar__send__val[1'(i)];
        response_crossbar__send__rdy[1'(i)] = send_rdata__rdy[1'( 1'(i) )];
      end
      else if ( 1'(i) == 1'( __const__num_rd_tiles_at_update_all ) ) begin
        __tmpvar__update_all_from_cgra_id = response_crossbar__send__msg[1'(i)].src_cgra;
        __tmpvar__update_all_from_tile_id = response_crossbar__send__msg[1'(i)].src_tile;
        send_to_noc_load_response_pkt__msg = { cgra_id, __tmpvar__update_all_from_cgra_id, idTo2d_x_lut[cgra_id], idTo2d_y_lut[cgra_id], idTo2d_x_lut[__tmpvar__update_all_from_cgra_id], idTo2d_y_lut[__tmpvar__update_all_from_cgra_id], 3'd0, __tmpvar__update_all_from_tile_id, response_crossbar__send__msg[1'(i)].remote_src_port, 8'd0, 2'd0, { 6'( __const__CMD_LOAD_RESPONSE ), response_crossbar__send__msg[1'(i)].data, response_crossbar__send__msg[1'(i)].addr, 119'd0, 3'd0 } };
        send_to_noc_load_response_pkt__val = response_crossbar__send__val[1'(i)];
        response_crossbar__send__rdy[1'(i)] = send_to_noc_load_response_pkt__rdy;
      end
      else if ( 1'( __const__has_dma_ports_at_update_all ) ) begin
        send_to_controller_spm_rd_resp__msg = response_crossbar__send__msg[1'(i)].data.payload;
        send_to_controller_spm_rd_resp__val = response_crossbar__send__val[1'(i)];
        response_crossbar__send__rdy[1'(i)] = send_to_controller_spm_rd_resp__rdy;
      end
    send_to_noc_load_request_pkt__msg = { cgra_id, 2'd0, idTo2d_x_lut[cgra_id], idTo2d_y_lut[cgra_id], 1'd0, 1'd0, 3'd0, 3'd0, read_crossbar__send__msg[2'( __const__num_banks_per_cgra_at_update_all )].src, 8'd0, 2'd0, { 6'( __const__CMD_LOAD_REQUEST ), 35'd0, read_crossbar__send__msg[2'( __const__num_banks_per_cgra_at_update_all )].addr, 119'd0, 3'd0 } };
    send_to_noc_load_request_pkt__val = read_crossbar__send__val[2'( __const__num_banks_per_cgra_at_update_all )];
    recv_from_noc_load_response_pkt__rdy = response_crossbar__recv__rdy[2'( __const__num_banks_per_cgra_at_update_all )];
    response_crossbar__recv__val[2'( __const__num_banks_per_cgra_at_update_all )] = recv_from_noc_load_response_pkt__val;
    response_crossbar__recv__msg[2'( __const__num_banks_per_cgra_at_update_all )] = { 2'( __const__num_banks_per_cgra_at_update_all ), recv_from_noc_load_response_pkt__msg.remote_src_port, recv_from_noc_load_response_pkt__msg.payload.data_addr, recv_from_noc_load_response_pkt__msg.payload.data, recv_from_noc_load_response_pkt__msg.src, recv_from_noc_load_response_pkt__msg.src_tile_id, 1'd0 };
    read_crossbar__send__rdy[2'( __const__num_banks_per_cgra_at_update_all )] = send_to_noc_load_request_pkt__rdy;
    send_to_noc_store_pkt__msg = { cgra_id, 2'd0, idTo2d_x_lut[cgra_id], idTo2d_y_lut[cgra_id], 1'd0, 1'd0, 3'd0, 3'd0, 1'(write_crossbar__send__msg[2'( __const__num_banks_per_cgra_at_update_all )].src), 8'd0, 2'd0, { 6'( __const__CMD_STORE_REQUEST ), write_crossbar__send__msg[2'( __const__num_banks_per_cgra_at_update_all )].data, write_crossbar__send__msg[2'( __const__num_banks_per_cgra_at_update_all )].addr, 119'd0, 3'd0 } };
    send_to_noc_store_pkt__val = write_crossbar__send__val[2'( __const__num_banks_per_cgra_at_update_all )];
    write_crossbar__send__rdy[2'( __const__num_banks_per_cgra_at_update_all )] = send_to_noc_store_pkt__rdy;
  end

  assign memory_wrapper__clk[0] = clk;
  assign memory_wrapper__reset[0] = reset;
  assign memory_wrapper__clk[1] = clk;
  assign memory_wrapper__reset[1] = reset;
  assign read_crossbar__clk = clk;
  assign read_crossbar__reset = reset;
  assign write_crossbar__clk = clk;
  assign write_crossbar__reset = reset;
  assign response_crossbar__clk = clk;
  assign response_crossbar__reset = reset;
  assign idTo2d_x_lut[0] = 1'd0;
  assign idTo2d_y_lut[0] = 1'd0;
  assign idTo2d_x_lut[1] = 1'd1;
  assign idTo2d_y_lut[1] = 1'd0;
  assign idTo2d_x_lut[2] = 1'd0;
  assign idTo2d_y_lut[2] = 1'd1;
  assign idTo2d_x_lut[3] = 1'd1;
  assign idTo2d_y_lut[3] = 1'd1;
  assign memory_wrapper__recv_rd__msg[0] = read_crossbar__send__msg[0];
  assign read_crossbar__send__rdy[0] = memory_wrapper__recv_rd__rdy[0];
  assign memory_wrapper__recv_rd__val[0] = read_crossbar__send__val[0];
  assign memory_wrapper__recv_wr__msg[0] = write_crossbar__send__msg[0];
  assign write_crossbar__send__rdy[0] = memory_wrapper__recv_wr__rdy[0];
  assign memory_wrapper__recv_wr__val[0] = write_crossbar__send__val[0];
  assign response_crossbar__recv__msg[0] = memory_wrapper__send__msg[0];
  assign memory_wrapper__send__rdy[0] = response_crossbar__recv__rdy[0];
  assign response_crossbar__recv__val[0] = memory_wrapper__send__val[0];
  assign memory_wrapper__recv_rd__msg[1] = read_crossbar__send__msg[1];
  assign read_crossbar__send__rdy[1] = memory_wrapper__recv_rd__rdy[1];
  assign memory_wrapper__recv_rd__val[1] = read_crossbar__send__val[1];
  assign memory_wrapper__recv_wr__msg[1] = write_crossbar__send__msg[1];
  assign write_crossbar__send__rdy[1] = memory_wrapper__recv_wr__rdy[1];
  assign memory_wrapper__recv_wr__val[1] = write_crossbar__send__val[1];
  assign response_crossbar__recv__msg[1] = memory_wrapper__send__msg[1];
  assign memory_wrapper__send__rdy[1] = response_crossbar__recv__rdy[1];
  assign response_crossbar__recv__val[1] = memory_wrapper__send__val[1];

endmodule
